import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String bound = Integer.toString(n);
        int[] p = new int[n];
        boolean impossible = false;
        for (int i = 0; i < n; i++) {
            String word = next();
            if (impossible) continue;
            // Compare the decimal text with n without converting huge numbers.
            int k = 0;
            if (k < word.length() && (word.charAt(k) == '+' || word.charAt(k) == '-')) k++;
            while (k < word.length() && word.charAt(k) == '0') k++;
            String digits = k < word.length() ? word.substring(k) : "0";
            if (digits.length() > bound.length() || (digits.length() == bound.length() && digits.compareTo(bound) > 0))
                impossible = true;
            else p[i] = Integer.parseInt(digits);
        }
        if (impossible) {
            System.out.println("None");
            return;
        }
        // Stable counting sort of the indices by p (all values are in 0..n).
        int[] start = new int[n + 2];
        for (int v : p) start[v + 1]++;
        for (int v = 0; v <= n; v++) start[v + 1] += start[v];
        int[] order = new int[n];
        for (int i = 0; i < n; i++) order[start[p[i]]++] = i;
        int left = 0, right = n - 1, offset = 0;
        int[] a = new int[n];
        // Peel off the element with the largest remaining absolute value each step.
        for (int remaining = n; remaining > 0; remaining--) {
            if (p[order[left]] < offset || p[order[right]] > offset + remaining) {
                System.out.println("None");
                return;
            }
            if (p[order[left]] == offset) {
                a[order[left++]] = -remaining;
            } else if (p[order[right]] == offset + remaining) {
                a[order[right--]] = remaining;
                offset++;
            } else {
                System.out.println("None");
                return;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	bound := strconv.Itoa(n)
	p := make([]int, n)
	impossible := false
	for i := 0; i < n; i++ {
		word := string(token())
		if impossible {
			continue
		}
		// Compare the decimal text with n without converting huge numbers.
		k := 0
		if k < len(word) && (word[k] == '+' || word[k] == '-') {
			k++
		}
		for k < len(word) && word[k] == '0' {
			k++
		}
		digits := "0"
		if k < len(word) {
			digits = word[k:]
		}
		if len(digits) > len(bound) || (len(digits) == len(bound) && digits > bound) {
			impossible = true
		} else {
			p[i], _ = strconv.Atoi(digits)
		}
	}
	if impossible {
		fmt.Println("None")
		return
	}
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return p[order[a]] < p[order[b]] })
	left, right, offset := 0, n-1, 0
	a := make([]int, n)
	// Peel off the element with the largest remaining absolute value each step.
	for remaining := n; remaining > 0; remaining-- {
		if p[order[left]] < offset || p[order[right]] > offset+remaining {
			fmt.Println("None")
			return
		}
		if p[order[left]] == offset {
			a[order[left]] = -remaining
			left++
		} else if p[order[right]] == offset+remaining {
			a[order[right]] = remaining
			right--
			offset++
		} else {
			fmt.Println("None")
			return
		}
	}
	out := make([]string, n)
	for i, v := range a {
		out[i] = strconv.Itoa(v)
	}
	fmt.Println(strings.Join(out, " "))
}
